23	TEST_CASE("state_drain primes dmactive then issues haltreq before any read")
24	{
25	  RecordingBus bus;
26	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
27	
28	  hybrid::StateDrain drain(bus);
29	  (void) drain.drain();
30	
31	  REQUIRE(bus.ops.size() >= 2);
32	  CHECK(bus.ops[0].kind == DmiOp::Kind::Write);
33	  CHECK(bus.ops[0].reg == RD::kDmcontrol);
34	  CHECK((bus.ops[0].value & RD::kDmcontrolDmactive) != 0u);
35	  CHECK((bus.ops[0].value & RD::kDmcontrolHaltreq) == 0u);
36	
37	  CHECK(bus.ops[1].kind == DmiOp::Kind::Write);
38	  CHECK(bus.ops[1].reg == RD::kDmcontrol);
39	  CHECK((bus.ops[1].value & RD::kDmcontrolDmactive) != 0u);
40	  CHECK((bus.ops[1].value & RD::kDmcontrolHaltreq) != 0u);
41	}
