57	    if (op.kind == DmiOp::Kind::Write && op.reg == RD::kCommand) {
58	      const uint16_t regno = op.value & 0xffffu;
59	      CHECK(regno != hybrid::regno_gpr(0));
60	    }
61	  }
62	}
