180	TEST_CASE("drain_with_passthrough with HYBRID_FLAG_FP: FP reads issued after GPR reads")
181	{
182	  RecordingBus bus;
183	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
184	
185	  hybrid_state_v1 input{};
186	  input.magic   = HYBRID_STATE_MAGIC;
187	  input.version = HYBRID_STATE_VERSION;
188	  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_FP;
189	  input.priv    = 3;
190	
191	  hybrid::StateDrain drain(bus);
192	  (void) drain.drain_with_passthrough(input);
193	
194	  std::optional<std::size_t> last_gpr_cmd;
195	  std::optional<std::size_t> first_fpr_cmd;
196	  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
197	    const auto& op = bus.ops[i];
198	    if (op.kind != DmiOp::Kind::Write || op.reg != RD::kCommand) continue;
199	    const uint16_t regno = op.value & 0xFFFFu;
200	    if (regno >= hybrid::regno_gpr(1) && regno <= hybrid::regno_gpr(31))
201	      last_gpr_cmd = i;
202	    if (!first_fpr_cmd
203	        && regno >= hybrid::regno_fpr(0) && regno <= hybrid::regno_fpr(31))
204	      first_fpr_cmd = i;
205	  }
206	  REQUIRE(last_gpr_cmd.has_value());
207	  REQUIRE(first_fpr_cmd.has_value());
208	  CHECK(*last_gpr_cmd < *first_fpr_cmd);
209	}
