212	{
213	  RecordingBus bus;
214	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
215	
216	  hybrid_state_v1 input{};
217	  input.magic   = HYBRID_STATE_MAGIC;
218	  input.version = HYBRID_STATE_VERSION;
219	  input.flags   = HYBRID_FLAG_RV64;  // no HYBRID_FLAG_FP
220	  input.priv    = 3;
221	  for (int i = 0; i < 32; ++i) input.fpr[i] = 0xdeadbeef00000000ULL + i;
222	
223	  hybrid::StateDrain drain(bus);
224	  const auto state = drain.drain_with_passthrough(input);
225	
226	  // No FPR COMMAND reads issued.
227	  for (const auto& op : bus.ops) {
228	    if (op.kind != DmiOp::Kind::Write || op.reg != RD::kCommand) continue;
229	    const uint16_t regno = op.value & 0xFFFFu;
230	    const bool is_fpr = regno >= hybrid::regno_fpr(0)
