277	TEST_CASE("drain_with_passthrough with HYBRID_FLAG_V: V CSR reads issued after GPR reads")
278	{
279	  RecordingBus bus;
280	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
281	
282	  hybrid_state_v1 input{};
283	  input.magic   = HYBRID_STATE_MAGIC;
284	  input.version = HYBRID_STATE_VERSION;
285	  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_V;
286	  input.priv    = 3;
287	
288	  hybrid::StateDrain drain(bus);
289	  (void) drain.drain_with_passthrough(input);
290	
291	  // Find the last GPR COMMAND read and the first V CSR COMMAND read.
292	  std::optional<std::size_t> last_gpr_cmd;
293	  std::optional<std::size_t> first_vcsr_cmd;
294	  const std::initializer_list<uint16_t> vcsr_regnos = {
295	    hybrid::regno_csr(RD::kCsrVstart),
296	    hybrid::regno_csr(RD::kCsrVxsat),
297	    hybrid::regno_csr(RD::kCsrVxrm),
298	    hybrid::regno_csr(RD::kCsrVcsr),
299	    hybrid::regno_csr(RD::kCsrVtype),
300	    hybrid::regno_csr(RD::kCsrVl),
301	  };
302	  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
303	    const auto& op = bus.ops[i];
304	    if (op.kind != DmiOp::Kind::Write || op.reg != RD::kCommand) continue;
305	    const uint16_t regno = op.value & 0xFFFFu;
306	    // Only register READS matter here. The V-data dump sweep also issues GPR
307	    // WRITES (x5/x6/x7 scratch) at the end of drain; those are not the
308	    // architectural GPR reads this ordering check is about.
309	    const bool is_read = ((op.value >> 16) & 1u) == 0u;
310	    if (is_read && regno >= hybrid::regno_gpr(1) && regno <= hybrid::regno_gpr(31))
311	      last_gpr_cmd = i;
312	    for (uint16_t vcsr : vcsr_regnos)
313	      if (is_read && !first_vcsr_cmd && regno == vcsr)
314	        first_vcsr_cmd = i;
315	  }
316	  REQUIRE(last_gpr_cmd.has_value());
317	  REQUIRE(first_vcsr_cmd.has_value());
318	  CHECK(*last_gpr_cmd < *first_vcsr_cmd);
319	}
