351	TEST_CASE("drain_with_passthrough with HYBRID_FLAG_V: PB dumps v0..v31 to scratch "
352	          "after the architectural counter/CSR reads")
353	{
354	  RecordingBus bus;
355	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
356	
357	  hybrid_state_v1 input{};
358	  input.magic   = HYBRID_STATE_MAGIC;
359	  input.version = HYBRID_STATE_VERSION;
360	  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_V;
361	  input.priv    = 3;
362	  input.vlenb   = 64;
363	
364	  hybrid::StateDrain drain(bus);
365	  (void) drain.drain_with_passthrough(input);
366	
367	  // (a) every v0..v31 is dumped via a vse8.v executed in the Program Buffer.
368	  std::vector<int> missing;
369	  std::optional<std::size_t> first_vse_idx;
370	  for (uint16_t v = 0; v < 32; ++v) {
371	    const uint32_t want = hybrid::encode_vse8_v(static_cast<uint8_t>(v), 7);
372	    std::optional<std::size_t> at;
373	    for (std::size_t i = 0; i < bus.ops.size(); ++i) {
374	      const auto& op = bus.ops[i];
375	      if (op.kind == DmiOp::Kind::Write && op.reg == hybrid::kProgbuf0
376	          && op.value == want) { at = i; break; }
377	    }
378	    if (!at) { missing.push_back(v); continue; }
379	    if (!first_vse_idx || *at < *first_vse_idx) first_vse_idx = at;
380	  }
381	  CHECK(missing.empty());
382	  REQUIRE(first_vse_idx.has_value());
383	
384	  // (b) the dump sweep runs AFTER the mcycle/minstret reads, so the sweep's
385	  //     vse8.v insns (and any counter increments) cannot corrupt the drained
386	  //     counters. minstret(0xB02) is the last counter read before the sweep.
387	  std::optional<std::size_t> minstret_read_idx;
388	  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
389	    const auto& op = bus.ops[i];
390	    if (op.kind != DmiOp::Kind::Write || op.reg != RD::kCommand) continue;
391	    const auto regno   = static_cast<uint16_t>(op.value & 0xFFFFu);
392	    const bool is_read = ((op.value >> 16) & 1u) == 0u;
393	    if (is_read && regno == hybrid::regno_csr(0xB02)) minstret_read_idx = i;
394	  }
395	  REQUIRE(minstret_read_idx.has_value());
396	  CHECK(*minstret_read_idx < *first_vse_idx);
397	}
